with changed as (select id,jsonb_set(documents,'{2,body}',to_jsonb(replace(documents#>>'{2,body}','Las funciones de mapas, notificaciones y geocodificación pueden comunicar datos técnicos o coordenadas a los proveedores usados por la función.','Los mapas utilizan OpenStreetMap y la geocodificación utiliza su servicio Nominatim, que pueden recibir datos técnicos y las coordenadas consultadas. Al pulsar Abrir indicaciones se abre Google Maps con el destino seleccionado. Las notificaciones del navegador utilizan los servicios de entrega del dispositivo y sus suscripciones técnicas.'))) docs from public.legal_releases where status='draft' and version='2026-10-19.1') update public.legal_releases r set documents=c.docs,content_sha256=encode(sha256(convert_to(jsonb_build_object('version',r.version,'operator',r.operator,'documents',c.docs)::text,'UTF8')),'hex') from changed c where r.id=c.id;
